<script lang="ts">
 import '../app.css';
 import{page}from'$app/state';
 let{data,children}=$props();
 const primary=[{href:'/',label:'Results'},{href:'/agents',label:'Agents'},{href:'/broker',label:'Accounts'}];
 const more=[{href:'/twins',label:'Paper vs demo'},{href:'/night-lab/',label:'Night Lab'},{href:'/graveyard',label:'Graveyard'},{href:'/leverage',label:'Leverage'},{href:'/research',label:'Research'},{href:'/journal',label:'Journal'},{href:'/status',label:'System'}];
 const active=(href:string)=>href==='/'?page.url.pathname==='/'||page.url.pathname.startsWith('/runs'):page.url.pathname.startsWith(href);
</script>
<svelte:head><title>Trader</title><meta name="theme-color" content="#0d0d0d" media="(prefers-color-scheme: dark)"/><meta name="theme-color" content="#f9f9f7" media="(prefers-color-scheme: light)"/></svelte:head>
<div class="app"><header class="app-bar"><a class="brand" href="/">Trader</a><nav aria-label="Main">{#each primary as item}<a href={item.href} class:active={active(item.href)}>{item.label}</a>{/each}<details class="more"><summary>More</summary><div>{#each more as item}<a href={item.href} class:active={active(item.href)} onclick={e=>e.currentTarget.closest('details')?.removeAttribute('open')}>{item.label}</a>{/each}</div></details></nav><a class="system-link" href="/status" aria-label={data.arena.up&&data.arena.streamConnected?'System online':'System connection needs attention'} title={data.arena.up&&data.arena.streamConnected?'Live':'Reconnecting'}><span class="status-dot" class:status-good={data.arena.up&&data.arena.streamConnected} class:status-warning={!data.arena.up||!data.arena.streamConnected}></span></a></header><main>{@render children()}</main></div>
<style>.app{min-height:100vh}.app-bar{height:60px;display:flex;align-items:center;gap:36px;border-bottom:1px solid var(--hairline);padding:0 28px;background:var(--surface)}.brand{font-size:17px;font-weight:650;text-decoration:none;letter-spacing:-.5px}nav{display:flex;align-items:center;gap:6px}nav>a,.more>summary{display:block;padding:6px 11px;border-radius:5px;color:var(--ink-2);text-decoration:none;font-size:13px;cursor:pointer;list-style:none}nav>a.active,.more a.active{background:var(--surface-2);color:var(--ink);font-weight:600}.more{position:relative}.more>div{position:absolute;top:36px;left:0;min-width:150px;padding:6px;background:var(--surface);border:1px solid var(--baseline);border-radius:6px;z-index:20;box-shadow:0 8px 24px var(--hairline)}.more a{display:block;padding:7px 10px;border-radius:4px;text-decoration:none;font-size:13px}.more a:hover{background:var(--surface-2)}.system-link{margin-left:auto;padding:8px}.system-link .status-dot{margin:0}main{max-width:1440px;margin:auto;padding:24px 28px 48px;min-width:0}@media(max-width:600px){.app-bar{height:52px;padding:0 14px;gap:14px}.brand{font-size:15px}nav{gap:0}nav>a,.more>summary{padding:6px 8px;font-size:12px}main{padding:18px 12px 36px}.system-link{padding:6px}}</style>
